const DEFAULT_CRYSTAL_WEB_LIGHT_OVERRIDE =
  process.env.NEXT_PUBLIC_MIR2_FIXED_LIGHT_SETTING?.trim() || "day";

function currentCrystalWebLightOverride(): string {
  if (typeof window === "undefined") return DEFAULT_CRYSTAL_WEB_LIGHT_OVERRIDE;
  return (
    new URLSearchParams(window.location.search).get("crystalLight") ??
    DEFAULT_CRYSTAL_WEB_LIGHT_OVERRIDE
  );
}

// Stable empty-list sentinel for the closed-window ExtraWindows props (Stage 3). When a window
// is closed we skip its adapter pass entirely and hand the (unread) list prop this shared
// frozen array, so the prop value keeps a stable identity flush-to-flush instead of allocating a
// fresh `[]`. `never[]` is assignable to every concrete `T[]` the windows expect.
const EMPTY_WINDOW_LIST: never[] = [];

type RuntimeStatus = {
  phase: string;
  message: string;
  ackKey?: string;
  imageKeys?: string[];
};

/** Local window guards update before a synchronous command callback can send. */
function useImmediateUiState<T>(initial: T) {
  const [state, setState] = useState(initial);
  const current = useRef(initial);
  const set = useCallback((next: T | ((previous: T) => T)) => {
    const resolved = typeof next === "function" ? (next as (previous: T) => T)(current.current) : next;
    current.current = resolved;
    setState(resolved);
  }, []);
  return [state, set, current] as const;
}

