function isLocalWebHost(hostname: string) {
  return hostname === "localhost" || hostname === "127.0.0.1" || hostname === "::1" || hostname === "[::1]";
}

function isSpectatorBrowserMode() {
  return typeof window !== "undefined" && new URLSearchParams(window.location.search).get("spectate") === "1";
}

function isAiLiveBrowserMode() {
  return typeof window !== "undefined" && new URLSearchParams(window.location.search).get("aiLive") === "1";
}

function isAiLiveAudioEnabled() {
  return typeof window !== "undefined" && new URLSearchParams(window.location.search).get("aiLiveAudio") === "1";
}

function resolveGatewayWebSocketUrl() {
  if (typeof window === "undefined") return CONFIGURED_GATEWAY_WS_URL || LOCAL_GATEWAY_WS_URL;
  const onLocalHost = isLocalWebHost(window.location.hostname);
  // The `gatewayWs` query override is a local-development convenience only.
  // Honoring it on a hosted origin would let a crafted link silently redirect a
  // player's WebSocket — and the login credentials sent over it — to an
  // attacker-controlled gateway, so it is ignored outside localhost.
  let resolved: string | null = null;
  if (onLocalHost) {
    const queryValue = new URLSearchParams(window.location.search).get("gatewayWs");
    if (queryValue && /^wss?:\/\//.test(queryValue)) resolved = queryValue;
  }
  resolved ??= CONFIGURED_GATEWAY_WS_URL || (onLocalHost ? LOCAL_GATEWAY_WS_URL : HOSTED_GATEWAY_WS_URL);
  if (!isSpectatorBrowserMode()) return resolved;

  const pageQuery = new URLSearchParams(window.location.search);
  const spectatorUrl = new URL(resolved, window.location.href);
  spectatorUrl.pathname = spectatorUrl.pathname.replace(/\/ws\/?$/, "/spectator/ws");
  if (!spectatorUrl.pathname.endsWith("/spectator/ws")) {
    spectatorUrl.pathname = "/spectator/ws";
  }
  const mappings = [
    ["spectateMap", "map"],
    ["spectateTarget", "target"],
    ["spectateDelayMs", "delayMs"],
    ["spectateMode", "mode"],
    ["spectateToken", "token"],
    ["replayId", "replayId"],
  ] as const;
  for (const [source, target] of mappings) {
    const value = pageQuery.get(source);
    if (value) spectatorUrl.searchParams.set(target, value);
  }
  return spectatorUrl.toString();
}

function safeGatewayUrlForDiagnostics(url: string) {
  try {
    const safe = new URL(url);
    if (safe.searchParams.has("token")) safe.searchParams.set("token", "[redacted]");
    return safe.toString();
  } catch {
    return url;
  }
}

function markMir2CacheMilestone(name: string, detail?: Record<string, unknown>) {
  if (typeof window === "undefined") return;
  const metricsWindow = window as typeof window & {
    __mir2CacheMetrics?: {
      markMilestone?: (name: string, detail?: Record<string, unknown>) => unknown;
    };
    __mir2PendingCacheMilestones?: Array<{ name: string; detail?: Record<string, unknown> }>;
  };
  if (metricsWindow.__mir2CacheMetrics?.markMilestone) {
    metricsWindow.__mir2CacheMetrics.markMilestone(name, detail);
    return;
  }
  metricsWindow.__mir2PendingCacheMilestones = [
    ...(metricsWindow.__mir2PendingCacheMilestones ?? []),
    { name, detail },
  ].slice(-50);
}

type AssetPrewarmStageName = "login" | "character-select" | "game";

function requestAssetPrewarmStage(stage: AssetPrewarmStageName) {
  if (typeof window === "undefined") return;
  const cacheWindow = window as typeof window & {
    __mir2AssetCachePrewarmStage?: (stage: AssetPrewarmStageName) => Promise<void>;
    __mir2PendingAssetPrewarmStage?: AssetPrewarmStageName;
  };
  cacheWindow.__mir2PendingAssetPrewarmStage = stage;
  void cacheWindow.__mir2AssetCachePrewarmStage?.(stage);
}

function scheduleBevyRuntimeCacheRecovery(message: string) {
  if (typeof window === "undefined") return false;
  if (!message.includes("WebAssembly.instantiate") || !message.includes("mir2_bevy_runtime_bg.js")) {
    return false;
  }

  const nextUrl = new URL(window.location.href);
  if (nextUrl.searchParams.get("runtimeRecovery") === "1") return false;

  markMir2CacheMilestone("bevyRuntimeCacheRecovery", {
    message,
    runtimeVersion: BEVY_RUNTIME_VERSION,
  });

  nextUrl.searchParams.set("runtimeRecovery", "1");
  nextUrl.searchParams.set("runtimeBust", String(Date.now()));

  let reloaded = false;
  const reloadOnce = () => {
    if (reloaded) return;
    reloaded = true;
    window.location.replace(nextUrl.toString());
  };

  const cacheWindow = window as typeof window & {
    __mir2AssetCacheReset?: (options?: { reload?: boolean }) => Promise<unknown>;
  };
  const resetPromise = cacheWindow.__mir2AssetCacheReset?.({ reload: false });
  if (resetPromise) {
    void resetPromise.finally(reloadOnce);
    window.setTimeout(reloadOnce, 1200);
  } else {
    window.setTimeout(reloadOnce, 150);
  }

  return true;
}

