// Death → town-revive overlay (mirrors Crystal's `GameScene` DiedTip Yes/No box,
// GameScene.cs:1271-1287). Shown while the self player is dead; the button sends the
// `townRevive` command and the server's `Revived` reply dismisses it (HP restored,
// respawned at the bind/town point). Presentational only — all state lives in page.
function DeathReviveOverlay({
  title,
  message,
  reviveLabel,
  revivingLabel,
  busy,
  onRevive,
}: {
  title: string;
  message: string;
  reviveLabel: string;
  revivingLabel: string;
  busy: boolean;
  onRevive: () => void;
}) {
  return (
    <div
      role="dialog"
      aria-modal="true"
      aria-label={title}
      style={{
        position: "fixed",
        inset: 0,
        zIndex: 4000,
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
        background: "rgba(0, 0, 0, 0.62)",
      }}
    >
      <div
        style={{
          minWidth: 280,
          maxWidth: 360,
          padding: "22px 26px",
          textAlign: "center",
          border: "1px solid #5a4326",
          borderRadius: 6,
          background: "linear-gradient(180deg, #2a2118, #18120c)",
          boxShadow: "0 8px 28px rgba(0, 0, 0, 0.6)",
          color: "#e8d9b5",
        }}
      >
        <div style={{ fontSize: 20, fontWeight: 700, color: "#d9484b", marginBottom: 8 }}>{title}</div>
        <div style={{ fontSize: 13, lineHeight: 1.5, marginBottom: 18, color: "#c9b890" }}>{message}</div>
        <button
          type="button"
          onClick={onRevive}
          disabled={busy}
          data-testid="town-revive-button"
          style={{
            width: "100%",
            padding: "10px 0",
            fontSize: 14,
            fontWeight: 600,
            cursor: busy ? "default" : "pointer",
            color: busy ? "#9b8a63" : "#1a130b",
            background: busy ? "#4a3a22" : "linear-gradient(180deg, #e8c873, #c79a3e)",
            border: "1px solid #5a4326",
            borderRadius: 4,
          }}
        >
          {busy ? revivingLabel : reviveLabel}
        </button>
      </div>
    </div>
  );
}

// Render-perf Stage 5b: store-bound OnchainMinePanel. The panel reads only one
// low-frequency world slice (`world.mineNodes`, via the derived `veinStage`), yet
// the old `veinStage={world.mineNodes.find(...)}` callsite recomputed it on every
// coalesced `setWorld` flush — re-rendering this whole HUD on unrelated combat /
// movement packets. This wrapper subscribes to the world store directly with
// `useWorldSelector`, so it re-renders only when the vein's stage actually
// changes. The selector returns a primitive (`number | null`), so its identity is
// already stable via `Object.is` — no custom `isEqual` needed. Proves the Stage-5
// pattern on the safest (lowest-frequency) consumer before any HUD migration.
function OnchainMinePanelWithStore({
  store,
  veinLocation,
  ...rest
}: Omit<OnchainMinePanelProps, "veinStage"> & { store: WorldStore }) {
  const veinStage = useWorldSelector(
    store,
    (s) => s.mineNodes.find((node) => isOnchainVeinNode(node, veinLocation))?.stage ?? null,
  );
  return <OnchainMinePanel {...rest} veinLocation={veinLocation} veinStage={veinStage} />;
}

// Compatibility is a projection of the same loss-aware authoritative mailbox.
function adaptMailMessages(raw: Array<Record<string, unknown>> | undefined): MailMessageSummary[] {
  return (parseMailList(raw)??[]).map(m=>({id:m.mailId,from:m.senderName,subject:m.subject,body:m.message,gold:m.gold,
    read:m.opened,locked:m.locked,claimed:m.collected,canReply:m.canReply,contentKey:mailContentKey(m),date:"",
    items:m.items.map(i=>i.name||i.key||(i.itemIndex!==null?`Item #${i.itemIndex}`:"Item"))}));
}

// B-wave-2: parse the enriched quest objectives/rewards the gateway now emits.
// The backend uses `text` for an objective; the window wants `label`.
function questNumber(value: unknown): number | undefined {
  const parsed = typeof value === "number" ? value : typeof value === "string" ? Number(value) : NaN;
  return Number.isFinite(parsed) ? parsed : undefined;
}

function parseQuestObjectives(
  raw: unknown,
): Array<{ label: string; current?: number; required?: number; done?: boolean }> | undefined {
  if (!Array.isArray(raw)) return undefined;
  const list = raw.flatMap((entry) => {
    const record = (entry ?? {}) as Record<string, unknown>;
    const label =
      typeof record.text === "string" ? record.text : typeof record.label === "string" ? record.label : "";
    if (!label) return [];
    return [{
      label,
      current: questNumber(record.current),
      required: questNumber(record.required),
      ...(typeof record.done === "boolean" ? { done: record.done } : {}),
    }];
  });
  return list.length > 0 ? list : undefined;
}

function parseQuestRewards(
  raw: unknown,
): QuestEntry["rewards"] | undefined {
  if (!raw || typeof raw !== "object" || Array.isArray(raw)) return undefined;
  const record = raw as Record<string, unknown>;
  const parseItems = (value: unknown, selectable: boolean) => {
    if (!Array.isArray(value)) return undefined;
    const parsed = value.flatMap((entry) => {
      const itemRecord = (entry ?? {}) as Record<string, unknown>;
      const name = typeof itemRecord.name === "string" ? itemRecord.name : "";
      if (!name) return [];
      return [{
        name,
        count: questNumber(itemRecord.count),
        icon: questNumber(itemRecord.icon),
        itemIndex: questNumber(itemRecord.itemIndex),
        ...(selectable
          ? {
              selectable: true,
              // Preserve malformed on-wire selection metadata as invalid so the
              // shared action boundary cannot mistake it for an omitted index.
              selectionIndex: itemRecord.selectionIndex === undefined
                ? undefined
                : typeof itemRecord.selectionIndex === "number"
                  ? itemRecord.selectionIndex
                  : NaN,
            }
          : {}),
      }];
    });
    return parsed.length > 0 ? parsed : undefined;
  };
  const items = parseItems(record.items, false);
  const selectItems = parseItems(record.selectItems, true);
  const gold = questNumber(record.gold);
  const experience = questNumber(record.experience);
  const credit = questNumber(record.credit);
  if (
    gold === undefined
    && experience === undefined
    && credit === undefined
    && !items
    && !selectItems
  ) return undefined;
  return { gold, experience, credit, items, selectItems };
}

function upsertEntityInList(list: WorldEntity[], nextEntity: WorldEntity) {
  return list.some((entity) => entity.objectId === nextEntity.objectId)
    ? list.map((entity) => (entity.objectId === nextEntity.objectId ? { ...entity, ...nextEntity } : entity))
    : [...list, nextEntity];
}

function patchEntityInList(
  list: WorldEntity[],
  objectId: string,
  updater: (entity: WorldEntity) => WorldEntity,
) {
  return list.map((entity) => (entity.objectId === objectId ? updater(entity) : entity));
}

function withCrystalSelfPacketMovement(
  nextEntity: WorldEntity,
  previousEntity: WorldEntity,
  packet: string,
  disposition: CrystalSelfAckDisposition,
  now: number,
): WorldEntity {
  if (packet === "UserLocation") {
    if (disposition === "confirmed" || disposition === "staleEcho") {
      return {
        ...nextEntity,
        ...preservedMovementAnimation(previousEntity, nextEntity.x, nextEntity.y, now),
      };
    }

    return {
      ...nextEntity,
      movementAnimation: undefined,
      movementStartedAt: undefined,
      movementUntil: undefined,
      movementFrameCount: undefined,
    };
  }

  return withPacketMovementAnimation(nextEntity, previousEntity, packet, now);
}

function withPacketMovementAnimation(
  nextEntity: WorldEntity,
  previousEntity: WorldEntity,
  packet: string,
  now: number,
): WorldEntity {
  const animation = packetMovementAnimation(packet, previousEntity, nextEntity);
  if (!animation) {
    return {
      ...nextEntity,
      movementAnimation: undefined,
      movementStartedAt: undefined,
      movementUntil: undefined,
      movementFrameCount: undefined,
    };
  }

  const mode = animation === "running" ? "run" : "walk";
  const movementProfile = crystalEntityMovementAnimationProfile(nextEntity, mode);
  const movementFrameCount = movementProfile.frameCount;
  return {
    ...nextEntity,
    movementAnimation: animation,
    movementStartedAt: now,
    movementUntil: now + movementFrameCount * movementProfile.frameIntervalMs,
    movementFrameCount,
  };
}

function bevyMovementShadowModeForRemotePacket(
  packet: string,
): BevyMovementShadowMode | null {
  switch (packet) {
    case "ObjectWalk":
    case "ObjectPushed":
    case "ObjectBackStep":
      return "walk";
    case "ObjectRun":
    case "ObjectDash":
    case "ObjectDashAttack":
      return "run";
    case "ObjectTurn":
    case "ObjectDashFail":
    case "ObjectSitDown":
      return "turn";
    default:
      return null;
  }
}

function packetMovementAnimation(
  packet: string,
  previousEntity: WorldEntity,
  nextEntity: WorldEntity,
): "walking" | "running" | null {
  switch (packet) {
    case "ObjectRun":
    case "ObjectDash":
    case "UserDash":
    case "ObjectDashAttack":
    case "UserDashAttack":
    case "UserAttackMove":
      return "running";
    case "ObjectWalk":
    case "ObjectBackStep":
    case "ObjectPushed":
    case "Pushed":
      return "walking";
    case "ObjectDashFail":
    case "UserDashFail":
      return null;
    case "UserLocation": {
      const distance = Math.max(
        Math.abs(nextEntity.x - previousEntity.x),
        Math.abs(nextEntity.y - previousEntity.y),
      );
      if (distance <= 0) return null;
      return distance > 1 ? "running" : "walking";
    }
    default:
      return null;
  }
}

function preservedMovementAnimation(
  previousEntity: WorldEntity | undefined,
  x: number,
  y: number,
  now: number,
): Pick<
  WorldEntity,
  "movementAnimation" | "movementStartedAt" | "movementUntil" | "movementFrameCount"
> {
  if (
    previousEntity?.movementAnimation &&
    previousEntity.movementStartedAt !== undefined &&
    previousEntity.movementUntil !== undefined &&
    previousEntity.movementUntil > now &&
    previousEntity.x === x &&
    previousEntity.y === y
  ) {
    return {
      movementAnimation: previousEntity.movementAnimation,
      movementStartedAt: previousEntity.movementStartedAt,
      movementUntil: previousEntity.movementUntil,
      movementFrameCount: previousEntity.movementFrameCount,
    };
  }

  return {};
}

function upsertGroundDropInList(list: GroundDrop[], nextDrop: GroundDrop) {
  return list.some((drop) => drop.objectId === nextDrop.objectId)
    ? list.map((drop) => (drop.objectId === nextDrop.objectId ? { ...drop, ...nextDrop } : drop))
    : [...list, nextDrop];
}

/**
 * Resolve once both fixed Bevy canvases are mounted — either they're
 * already in the DOM, the shell has signalled readiness on mount (`window.__mir2BevyCanvasReady`
 * / the `"mir2:bevy-canvas-ready"` event it dispatches), or a MutationObserver sees it inserted.
 * Rejects after `timeoutMs`.
 *
 * The runtime selects either fixed canvas (apps/game-client/runtime/src/lib.rs),
 * rendered inside the lazily-mounted (dynamic, ssr:false) OriginalClientShell — booting the WASM
 * before its selected canvas exists makes bevy_winit panic.
 */
async function waitForBevyCanvas(timeoutMs = 15000): Promise<void> {
  if (typeof document === "undefined") return;
  const isReady = () =>
    document.querySelector("#mir2-web3-canvas") !== null && document.querySelector("#mir2-quest-ui-canvas") !== null;
  if (isReady()) return;
  await new Promise<void>((resolve, reject) => {
    let settled = false;
    const finish = (ok: boolean) => {
      if (settled) return;
      settled = true;
      window.clearTimeout(timer);
      observer.disconnect();
      window.removeEventListener("mir2:bevy-canvas-ready", onSignal);
      if (ok) resolve();
      else reject(new Error("timed out waiting for fixed Bevy canvases"));
    };
    const onSignal = () => {
      if (isReady()) finish(true);
    };
    const observer = new MutationObserver(onSignal);
    const timer = window.setTimeout(() => finish(false), timeoutMs);
    window.addEventListener("mir2:bevy-canvas-ready", onSignal);
    observer.observe(document.documentElement, { childList: true, subtree: true });
    // Re-check in case it mounted between the initial check and listener/observer setup.
    if (isReady()) finish(true);
  });
}

const bevyRuntimeModuleLoads = new Map<string, Promise<RuntimeModule>>();

async function loadBevyRuntimeModule(backend: BevyRuntimeBackend, startup: BevyRuntimeStartup): Promise<RuntimeModule> {
  const selectedPackage = getBevyRuntimePackageForBackend(startup, backend);
  if (!selectedPackage || !startup.manifest) throw new Error("Runtime package is unavailable for fixed startup mode");
  const { moduleUrl: runtimePath, wasmUrl: runtimeWasmPath } = createBevyRuntimeUrls(
    startup.manifest.version,
    selectedPackage.id,
    BEVY_RUNTIME_ASSET_BASE_URL,
  );
  const existing = bevyRuntimeModuleLoads.get(runtimePath);
  if (existing) return existing;
  const loading = initializeBevyRuntimeModule(runtimePath, runtimeWasmPath);
  bevyRuntimeModuleLoads.set(runtimePath, loading);
  return loading;
}

async function initializeBevyRuntimeModule(runtimePath: string, runtimeWasmPath: string): Promise<RuntimeModule> {
  const runtime = (await import(
    /* webpackIgnore: true */ runtimePath
  )) as RuntimeModule;

  if (typeof runtime.default === "function") {
    // The runtime attaches to one of the fixed canvases on boot; make sure both exist first
    // (it lives in the lazily-mounted OriginalClientShell) to avoid a bevy_winit panic.
    await waitForBevyCanvas();
    const controller = new AbortController();
    const timeout = window.setTimeout(() => controller.abort(), BEVY_RUNTIME_BOOT_TIMEOUT_MS);
    try {
      await runtime.default({
        module_or_path: new Request(runtimeWasmPath, { signal: controller.signal }),
      });
    } finally {
      window.clearTimeout(timeout);
    }
  }

  return runtime;
}

function selectBevyRuntimeBackend(
  params: URLSearchParams,
  support: BevyRuntimeSupport,
): BevyRuntimeBackend | null {
  const requestedBackend = normalizeBevyRuntimeBackendOverride(
    params.get("bevyBackend") ?? safeLocalStorageGet("mir2-bevy-backend"),
  );

  if (requestedBackend === "webgl2") {
    return support.webgl2 ? "webgl2" : null;
  }

  if (requestedBackend === "webgpu") {
    return support.webgpu ? "webgpu" : support.webgl2 ? "webgl2" : null;
  }

  if (support.webgpu) return "webgpu";
  if (support.webgl2) return "webgl2";
  return null;
}

function normalizeBevyRuntimeBackendOverride(value: string | null): BevyRuntimeBackend | null {
  const normalized = value?.trim().toLowerCase();
  if (normalized === "webgpu" || normalized === "gpu") return "webgpu";
  if (normalized === "webgl2" || normalized === "webgl" || normalized === "gl") return "webgl2";
  return null;
}

async function detectBevyRuntimeSupport(): Promise<BevyRuntimeSupport> {
  return {
    webgpu: await hasWebGpuSupport(),
    webgl2: hasWebGl2Support(),
  };
}

async function hasWebGpuSupport(): Promise<boolean> {
  try {
    const maybeNavigator = navigator as Navigator & {
      gpu?: { requestAdapter?: () => Promise<unknown> };
    };
    if (!window.isSecureContext || !maybeNavigator.gpu) {
      return false;
    }
    // `navigator.gpu` can exist while no adapter is actually obtainable — older Chrome,
    // Firefox <128, Safari <18, or Chrome launched with `--disable-gpu`. Booting the
    // WebGPU backend in that case panics inside bevy_render ("Unable to find a GPU") and
    // black-screens the client. Probe for a real adapter so we only report WebGPU support
    // when the runtime can actually create a device.
    const adapter = await maybeNavigator.gpu.requestAdapter?.();
    return Boolean(adapter);
  } catch {
    return false;
  }
}

function hasWebGl2Support() {
  try {
    const canvas = document.createElement("canvas");
    return Boolean(canvas.getContext("webgl2"));
  } catch {
    return false;
  }
}

function safeLocalStorageGet(key: string) {
  try {
    return window.localStorage.getItem(key);
  } catch {
    return null;
  }
}

function safeLocalStorageRemove(key: string) {
  try {
    window.localStorage.removeItem(key);
  } catch {
    // Storage may be unavailable (private mode / disabled cookies) — ignore.
  }
}

function createLogLine(
  text: string,
  tone: UiLogTone,
  channel: UiLogChannel,
  crystalChatType: CrystalChatTypeValue = crystalChatTypeForUiLog(tone, channel),
): UiLogLine {
  return {
    text,
    tone,
    channel,
    crystalChatType,
  };
}

function defaultLogChannel(tone: UiLogTone): UiLogChannel {
  if (tone === "network") {
    return "network";
  }

  return tone === "chat" ? "normal" : "system";
}

function gatewayChatChannel(value: unknown): UiLogChannel {
  if (typeof value !== "string") {
    return "normal";
  }

  switch (value.toLowerCase()) {
    case "shout":
    case "shout2":
    case "shout3":
      return "shout";
    case "trade":
      return "trade";
    case "whisperin":
    case "whisperout":
      return "whisper";
    case "group":
      return "group";
    case "guild":
      return "guild";
    case "mentor":
      return "mentor";
    case "relationship":
      return "relationship";
    case "system":
    case "system2":
      return "system";
    case "hint":
      return "hint";
    case "server":
      return "server";
    case "announcement":
    case "levelup":
      return "announcement";
    case "linemessage":
      return "line";
    default:
      return "normal";
  }
}

function gatewayChatTone(value: unknown): UiLogTone {
  const channel = gatewayChatChannel(value);
  return channel === "system" || channel === "hint" || channel === "announcement" ? "system" : "chat";
}

function gatewayCrystalChatType(value: unknown): CrystalChatTypeValue {
  if (typeof value !== "string") return CrystalChatType.Normal;

  switch (value.toLowerCase()) {
    case "shout":
      return CrystalChatType.Shout;
    case "system":
      return CrystalChatType.System;
    case "hint":
      return CrystalChatType.Hint;
    case "announcement":
      return CrystalChatType.Announcement;
    case "group":
      return CrystalChatType.Group;
    case "whisperin":
      return CrystalChatType.WhisperIn;
    case "whisperout":
      return CrystalChatType.WhisperOut;
    case "guild":
      return CrystalChatType.Guild;
    case "trainer":
      return CrystalChatType.Trainer;
    case "levelup":
      return CrystalChatType.LevelUp;
    case "system2":
      return CrystalChatType.System2;
    case "relationship":
      return CrystalChatType.Relationship;
    case "mentor":
      return CrystalChatType.Mentor;
    case "shout2":
      return CrystalChatType.Shout2;
    case "shout3":
      return CrystalChatType.Shout3;
    case "linemessage":
      return CrystalChatType.LineMessage;
    default:
      return CrystalChatType.Normal;
  }
}

function crystalChatTypeForUiLog(tone: UiLogTone, channel: UiLogChannel): CrystalChatTypeValue {
  switch (channel) {
    case "shout":
      return CrystalChatType.Shout;
    case "whisper":
      return CrystalChatType.WhisperIn;
    case "group":
      return CrystalChatType.Group;
    case "guild":
      return CrystalChatType.Guild;
    case "mentor":
      return CrystalChatType.Mentor;
    case "relationship":
      return CrystalChatType.Relationship;
    case "hint":
      return CrystalChatType.Hint;
    case "line":
      return CrystalChatType.LineMessage;
    case "announcement":
      return CrystalChatType.Announcement;
    case "system":
    case "server":
      return CrystalChatType.System;
    default:
      return tone === "system" ? CrystalChatType.System : CrystalChatType.Normal;
  }
}

function storageUnlockResultMessage(result: number, hasPassword: boolean) {
  switch (result) {
    case 0:
      return "Storage unlocked.";
    case 1:
      return "Storage password is required.";
    case 2:
      return "Storage password is incorrect.";
    case 3:
      return "Storage is not available.";
    case 4:
      return hasPassword ? "Storage unlock state is invalid." : "Storage password has not been set.";
    default:
      return `Storage unlock returned result ${result}.`;
  }
}

function storagePasswordResultMessage(result: number, removing: boolean, hasPassword: boolean) {
  switch (result) {
    case 0:
      return "Storage password service is not available.";
    case 1:
      return removing ? "Current storage password is required to remove it." : "Current storage password is required.";
    case 2:
      return "Current storage password is incorrect.";
    case 3:
      return "New storage password is invalid.";
    case 4:
      return removing
        ? "Storage password removed."
        : hasPassword
          ? "Storage password updated."
          : "Storage password cleared.";
    case 5:
      return "Storage password has not been set.";
    default:
      return `Storage password operation returned result ${result}.`;
  }
}

function storageResizeMessage(size: number, hasExpandedStorage: boolean) {
  if (size <= 0) {
    return "Storage layout updated.";
  }
  return hasExpandedStorage
    ? `Storage expanded to ${size} slots.`
    : `Storage layout updated: ${size} slots.`;
}

function equipmentSlotIndex(slot: EquipmentSlot): number {
  switch (slot) {
    case "weapon":
      return 0;
    case "armour":
      return 1;
    case "helmet":
      return 2;
    case "torch":
      return 3;
    case "necklace":
      return 4;
    case "braceletLeft":
      return 5;
    case "braceletRight":
      return 6;
    case "ringLeft":
      return 7;
    case "ringRight":
      return 8;
    case "amulet":
      return 9;
    case "belt":
      return 10;
    case "boots":
      return 11;
    case "stone":
      return 12;
    case "mount":
      return 13;
  }
}

function equipmentSlotFromIndex(index: number): EquipmentSlot | null {
  switch (index) {
    case 0:
      return "weapon";
    case 1:
      return "armour";
    case 2:
      return "helmet";
    case 3:
      return "torch";
    case 4:
      return "necklace";
    case 5:
      return "braceletLeft";
    case 6:
      return "braceletRight";
    case 7:
      return "ringLeft";
    case 8:
      return "ringRight";
    case 9:
      return "amulet";
    case 10:
      return "belt";
    case 11:
      return "boots";
    case 12:
      return "stone";
    case 13:
      return "mount";
    default:
      return null;
  }
}

function summarizeDebugWorldSnapshot(snapshot: GatewayWorldSnapshot) {
  return {
    tick: snapshot.tick,
    gold: snapshot.gold,
    playerHp: snapshot.playerHp,
    playerMaxHp: snapshot.playerMaxHp,
    playerMp: snapshot.playerMp,
    playerMaxMp: snapshot.playerMaxMp,
    playerExperience: snapshot.playerExperience,
    playerMaxExperience: snapshot.playerMaxExperience,
    currentWeight: snapshot.currentWeight,
    maxWeight: snapshot.maxWeight,
    freeBagSlots: snapshot.freeBagSlots,
    maxBagSlots: snapshot.maxBagSlots,
    inSafeZone: snapshot.inSafeZone,
    lightSetting: snapshot.lightSetting,
    inventoryItems: (snapshot.inventoryItems ?? []).map((item) => ({
      key: item.key,
      uniqueId: item.uniqueId,
      slot: item.slot,
      container: item.container,
      quantity: item.quantity,
    })),
    beltItems: (snapshot.beltItems ?? []).map((item) => ({
      key: item.key,
      uniqueId: item.uniqueId,
      slot: item.slot,
      quantity: item.quantity,
    })),
    storageItems: (snapshot.storageItems ?? []).map((item) => ({
      key: item.key,
      uniqueId: item.uniqueId,
      slot: item.slot,
      quantity: item.quantity,
    })),
    groundDrops: (snapshot.groundDrops ?? []).map((drop) => ({
      name: drop.name,
      objectId: drop.objectId,
      x: drop.x,
      y: drop.y,
      quantity: drop.quantity,
    })),
    npcScriptDiagnostics: (snapshot.npcScriptDiagnostics ?? []).map((diagnostic) => ({
      scriptKey: diagnostic.scriptKey,
      label: diagnostic.label,
      lineNumber: diagnostic.lineNumber,
      command: diagnostic.command,
      message: diagnostic.message,
    })),
  };
}

function itemClientReference(item: WorldItem) {
  if (typeof item.uniqueId === "number") {
    return item.uniqueId;
  }
  switch (item.container) {
    case "bag2":
      return 40 + item.slot;
    default:
      return item.slot;
  }
}

function itemMatchesPacketGrid(item: WorldItem, grid: string, uniqueId: number) {
  const normalizedGrid = grid.toLowerCase();
  if (normalizedGrid === "belt") {
    return item.container === "belt" && itemClientReference(item) === uniqueId;
  }
  if (normalizedGrid === "questinventory" || normalizedGrid === "quest_inventory") {
    return item.container === "quest" && itemClientReference(item) === uniqueId;
  }
  if (normalizedGrid === "storage") {
    return item.container === "storage" && itemClientReference(item) === uniqueId;
  }
  return (item.container === "bag1" || item.container === "bag2") && itemClientReference(item) === uniqueId;
}

function consumePacketItem(items: WorldItem[], grid: string, uniqueId: number, count: number) {
  let consumed = false;
  const nextItems = items.flatMap((item) => {
    if (consumed || !itemMatchesPacketGrid(item, grid, uniqueId)) {
      return [item];
    }
    consumed = true;
    if (item.quantity > count) {
      return [{ ...item, quantity: item.quantity - count }];
    }
    return [];
  });
  return consumed ? nextItems : items;
}

function stringifyId(value: unknown) {
  return typeof value === "number" ? String(value) : typeof value === "string" ? value : "0";
}

function numberOrZero(value: unknown) {
  return typeof value === "number" ? value : 0;
}

function numberOrUndefined(value: unknown) {
  return typeof value === "number" ? value : undefined;
}

function movementPointFromPacketPayload(payload: Record<string, unknown>) {
  const location = payload.location as { x?: unknown; y?: unknown } | undefined;
  return {
    x: numberOrZero(payload.x ?? location?.x),
    y: numberOrZero(payload.y ?? location?.y),
  };
}

function spriteFromPacket(payload: Record<string, unknown>, kind: EntityKind): GatewayWorldEntitySprite | null {
  if (kind === "player" || kind === "selfPlayer") {
    return playerSpriteFromPacket(payload);
  }

  if (kind === "monster") {
    return simpleSpriteFromPacket("Monster", numberOrUndefined(payload.image), 3);
  }

  if (kind === "npc") {
    return simpleSpriteFromPacket("NPC", numberOrUndefined(payload.image), 2);
  }

  return null;
}

function spriteFromSnapshotEntity(
  entity: GatewayWorldEntity,
  mapFileName: string | null | undefined,
  existingSprite: GatewayWorldEntitySprite | null,
): GatewayWorldEntitySprite | null {
  if (entity.sprite) {
    return entity.sprite;
  }
  if (existingSprite) {
    return existingSprite;
  }
  return fallbackCrystalActorSprite(
    entity.kind,
    entity.name,
    entity.objectId,
    entity.x,
    entity.y,
    mapFileName,
  );
}

function spriteFromPacketOrExisting(
  payload: Record<string, unknown>,
  kind: EntityKind,
  existingSprite: GatewayWorldEntitySprite | null,
  mapFileName: string | null | undefined,
): GatewayWorldEntitySprite | null {
  const sprite = spriteFromPacket(payload, kind);
  const location = payload.location as { x?: number; y?: number } | undefined;
  const packetImage = numberOrUndefined(payload.image);
  const fallbackSprite =
    kind === "npc" || kind === "monster"
      ? fallbackCrystalActorSprite(
          kind,
          stringOrFallback(payload.name, ""),
          numberOrUndefined(payload.objectId),
          numberOrUndefined(location?.x),
          numberOrUndefined(location?.y),
          mapFileName,
        )
      : null;

  if (!existingSprite || (kind !== "npc" && kind !== "monster")) {
    if ((kind === "npc" || kind === "monster") && packetImage === 0 && fallbackSprite) {
      return fallbackSprite;
    }
    return sprite ?? fallbackSprite;
  }
  if (!sprite) {
    return existingSprite;
  }

  if (packetImage === 0 && sprite.bodyLibrary !== existingSprite.bodyLibrary) {
    return existingSprite;
  }

  return sprite;
}

function fallbackCrystalActorSprite(
  kind: EntityKind,
  name: string,
  objectId: number | undefined,
  x: number | undefined,
  y: number | undefined,
  mapFileName: string | null | undefined,
): GatewayWorldEntitySprite | null {
  if (kind === "npc") {
    const byLocation =
      mapFileName && typeof x === "number" && typeof y === "number"
        ? CRYSTAL_NPC_SPRITE_BY_LOCATION.get(crystalActorLocationKey(mapFileName, name, x, y))
        : undefined;
    const byObjectId =
      typeof objectId === "number" ? CRYSTAL_NPC_SPRITE_BY_OBJECT_ID.get(objectId) : undefined;
    const npc = byLocation ?? (byObjectId?.map === mapFileName ? byObjectId : undefined) ?? byObjectId;
    return npc ? simpleSpriteFromPacket("NPC", npc.image, 2) : null;
  }

  if (kind === "monster") {
    const monster = CRYSTAL_MONSTER_SPRITE_BY_NAME.get(normalizeCrystalActorName(name));
    return monster ? simpleSpriteFromPacket("Monster", monster.image, 3) : null;
  }

  return null;
}

function crystalActorLocationKey(mapFileName: string, name: string, x: number, y: number) {
  return `${mapFileName}:${normalizeCrystalActorName(name)}:${Math.trunc(x)}:${Math.trunc(y)}`;
}

function normalizeCrystalActorName(value: string) {
  return value.trim().toLowerCase().replace(/[\s_]+/g, "_");
}

function playerSpriteFromPacket(payload: Record<string, unknown>): GatewayWorldEntitySprite {
  const armourShape = numberOrUndefined(payload.armour) ?? 0;
  const hairShape = numberOrUndefined(payload.hair) ?? 0;
  const weaponShape = numberOrUndefined(payload.weapon);
  const mountType = numberOrUndefined(payload.mountType) ?? -1;
  const ridingMount = payload.ridingMount === true && mountType >= 0;
  const classKey = mapClassKey(payload.class);
  const genderKey = mapGenderKey(payload.gender);
  const usesAssassinWeapon = typeof weaponShape === "number" && weaponShape >= 100 && weaponShape < 200;
  const usesArcherWeapon = typeof weaponShape === "number" && weaponShape >= 200;
  const bodyLibrary = `CArmour/${paddedLibraryIndex(armourShape, 2)}`;
  const hairLibrary = `CHair/${paddedLibraryIndex(hairShape, 2)}`;
  const weaponLibraries = playerWeaponLibraries(weaponShape);
  const frameBaseOffset = genderKey === "female" ? 808 : 0;
  const altFrameBaseOffset =
    classKey === "archer" && usesArcherWeapon
      ? genderKey === "female"
        ? 352
        : 0
      : classKey === "assassin" && usesAssassinWeapon
        ? genderKey === "female"
          ? 512
          : 0
        : null;

  return {
    bodyLibrary,
    hairLibrary,
    weaponLibrary: weaponLibraries.weaponLibrary,
    weaponLibrarySecondary: weaponLibraries.weaponLibrarySecondary,
    frameBaseOffset,
    weaponFrameOffset: weaponLibraries.weaponLibrary ? (genderKey === "female" ? 416 : 0) : null,
    altBodyLibrary:
      classKey === "archer" && usesArcherWeapon
        ? `ARArmour/${paddedLibraryIndex(armourShape, 2)}`
        : classKey === "assassin" && usesAssassinWeapon
          ? `AArmour/${paddedLibraryIndex(armourShape, 2)}`
          : null,
    altHairLibrary:
      classKey === "archer" && usesArcherWeapon
        ? `ARHair/${paddedLibraryIndex(hairShape, 2)}`
        : classKey === "assassin" && usesAssassinWeapon
          ? `AHair/${paddedLibraryIndex(hairShape, 2)}`
          : null,
    altWeaponLibrary: weaponLibraries.altWeaponLibrary,
    altWeaponLibrarySecondary: weaponLibraries.altWeaponLibrarySecondary,
    altFrameBaseOffset,
    altWeaponFrameOffset: altFrameBaseOffset,
    frameCount: 4,
    directionStride: 4,
    mountLibrary: ridingMount ? `Mount/${paddedLibraryIndex(mountType, 2)}` : null,
    mountFrameOffset: ridingMount ? 0 : null,
  };
}

function playerWeaponLibraries(weaponShape: number | undefined) {
  if (typeof weaponShape !== "number") {
    return {
      weaponLibrary: null,
      weaponLibrarySecondary: null,
      altWeaponLibrary: null,
      altWeaponLibrarySecondary: null,
    };
  }

  if (weaponShape >= 100 && weaponShape < 200) {
    const index = paddedLibraryIndex(weaponShape - 100, 2);
    return {
      weaponLibrary: null,
      weaponLibrarySecondary: null,
      altWeaponLibrary: `AWeapon/${index} R`,
      altWeaponLibrarySecondary: `AWeapon/${index} L`,
    };
  }

  if (weaponShape >= 200) {
    const index = paddedLibraryIndex(weaponShape - 200, 2);
    return {
      weaponLibrary: `ARWeapon/${index}`,
      weaponLibrarySecondary: null,
      altWeaponLibrary: `ARWeapon/${index} S`,
      altWeaponLibrarySecondary: null,
    };
  }

  return {
    weaponLibrary: `CWeapon/${paddedLibraryIndex(weaponShape, 2)}`,
    weaponLibrarySecondary: null,
    altWeaponLibrary: null,
    altWeaponLibrarySecondary: null,
  };
}

function simpleSpriteFromPacket(
  libraryRoot: "Monster" | "NPC",
  image: number | undefined,
  padding: number,
): GatewayWorldEntitySprite | null {
  if (typeof image !== "number") {
    return null;
  }

  return {
    bodyLibrary: `${libraryRoot}/${paddedLibraryIndex(image, padding)}`,
    hairLibrary: null,
    weaponLibrary: null,
    weaponLibrarySecondary: null,
    frameBaseOffset: 0,
    weaponFrameOffset: null,
    altBodyLibrary: null,
    altHairLibrary: null,
    altWeaponLibrary: null,
    altWeaponLibrarySecondary: null,
    altFrameBaseOffset: null,
    altWeaponFrameOffset: null,
    frameCount: 4,
    directionStride: 4,
  };
}

function paddedLibraryIndex(value: number, width: number) {
  return Math.max(0, Math.trunc(value)).toString().padStart(width, "0");
}

function transferKeyForWorldTile(
  transfers: MapTransferArea[],
  mapFileName: string | null,
  x: number,
  y: number,
) {
  const normalizedMap = mapFileName?.trim().toLowerCase().replace(/\.map$/, "") ?? null;
  return (
    transfers.find(
      (transfer) =>
        normalizedMap === transfer.mapFileName &&
        x >= transfer.minX &&
        x <= transfer.maxX &&
        y >= transfer.minY &&
        y <= transfer.maxY,
    )?.key ?? null
  );
}

function normalizeMapFileName(mapFileName: string | null) {
  return (mapFileName ?? "0").trim().replace(/\.map$/i, "").toLowerCase() || "0";
}

function shouldReloadCrystalScene(
  region: OriginalMapRegion | null,
  mapFileName: string,
  center: { x: number; y: number },
  viewportLayout: ViewportLayout = viewportLayoutForStage(),
) {
  if (!region) {
    return true;
  }

  if (normalizeMapFileName(region.mapFileName) !== mapFileName) {
    return true;
  }

  // Reload ONLY when the player nears the LOADED region's edge — NOT merely
  // because the chunk index flipped. The fetched region (SCENE_REQUEST_WIDTH/
  // HEIGHT) is far larger than one chunk (SCENE_CHUNK_*), so a chunk-boundary
  // crossing normally leaves the player amply inside the current region. The old
  // `loadedSceneKey !== sceneKey` early-return forced a reload on every chunk
  // flip, so walking along a chunk boundary re-fetched the scene every step and
  // re-rendered the whole map → flicker / misalignment + "stutter every few
  // steps". Measured: 77% of scene fetches were redundant re-fetches of the same
  // 1–2 chunks (one boundary re-fetched 30×). The margin check below already
  // covers genuine edge approach and teleports (player outside playBounds).
  const marginX = Math.max(4, Math.floor(Math.max(8, viewportLayout.rangeX * 0.75) / 2));
  const marginY = Math.max(4, Math.floor(Math.max(10, viewportLayout.rangeY) / 2));
  return (
    center.x <= region.playBounds.minX + marginX ||
    center.x >= region.playBounds.maxX - marginX ||
    center.y <= region.playBounds.minY + marginY ||
    center.y >= region.playBounds.maxY - marginY
  );
}

function originalMapRegionContainsTile(region: OriginalMapRegion | null, x: number, y: number) {
  if (!region) {
    return false;
  }
  return (
    x >= region.regionBounds.minX &&
    x <= region.regionBounds.maxX &&
    y >= region.regionBounds.minY &&
    y <= region.regionBounds.maxY
  );
}

function originalMapCellBlocksMovement(region: OriginalMapRegion | null, x: number, y: number) {
  if (!region) {
    return false;
  }
  const cell = region.cells.find((entry) => entry.x === x && entry.y === y);
  // Indexed Crystal doors stay routeable exactly like the original client:
  // CheckDoorOpen handles them immediately before sending a movement packet.
  // A legacy packaged closedDoor without an index cannot be opened safely and
  // therefore remains a hard blocker.
  const indexedDoor = Number.isInteger(cell?.doorIndex) && Number(cell?.doorIndex) > 0;
  return Boolean(cell?.blocked || (cell?.closedDoor && !indexedDoor));
}

function originalMapClosedDoorIndexOnMovementPath(
  region: OriginalMapRegion | null,
  source: { x: number; y: number },
  action: { point: { x: number; y: number }; direction: string },
) {
  if (!region) return null;
  const distance = Math.max(
    Math.abs(action.point.x - source.x),
    Math.abs(action.point.y - source.y),
  );
  for (let step = 1; step <= distance; step += 1) {
    const point = pointMoveInDirection(source, action.direction, step);
    const cell = region.cells.find((entry) => entry.x === point.x && entry.y === point.y);
    const doorIndex = Number(cell?.doorIndex);
    if (
      cell?.closedDoor === true &&
      cell.blocked !== true &&
      Number.isInteger(doorIndex) &&
      doorIndex > 0
    ) {
      return doorIndex & 0x7f;
    }
  }
  return null;
}

function setOriginalMapDoorClosed(
  region: OriginalMapRegion | null,
  doorIndex: number,
  closed: boolean,
) {
  if (!region) return region;
  let changed = false;
  const cells = region.cells.map((cell) => {
    if (Number(cell.doorIndex) !== doorIndex || cell.closedDoor === closed) return cell;
    changed = true;
    return { ...cell, closedDoor: closed };
  });
  return changed ? { ...region, cells } : region;
}

function crystalAttackActionDurationMs(
  entity: WorldEntity,
  animation: NonNullable<WorldEntity["attackAnimation"]>,
) {
  const frameSetAction = crystalFrameSetActionForState(
    crystalEntityFrameSet(entity),
    animation === "range" || animation === "spell" ? "attackRange" : "attackMelee",
    animation,
  );
  if (frameSetAction) return crystalFrameSetActionDurationMs(frameSetAction);
  if (animation === "spell") return 600;
  if (animation === "range" || animation === "melee3") {
    return 800;
  }

  return entity.kind === "monster" ? 600 : 600;
}

function crystalStruckActionDurationMs(entity: WorldEntity) {
  const action = crystalFrameSetActionForState(crystalEntityFrameSet(entity), "struck");
  if (action) return crystalFrameSetActionDurationMs(action);
  return entity.kind === "monster" ? 400 : 300;
}

function crystalDeathActionDurationMs(entity: WorldEntity) {
  const action = crystalFrameSetActionForState(crystalEntityFrameSet(entity), "dying");
  if (action) return crystalFrameSetActionDurationMs(action);
  return entity.kind === "monster" ? 1000 : 400;
}

function crystalReviveActionDurationMs(entity: WorldEntity) {
  const action = crystalFrameSetActionForState(crystalEntityFrameSet(entity), "reviving");
  if (action) return crystalFrameSetActionDurationMs(action);
  return crystalDeathActionDurationMs(entity);
}

function skillMatchesCrystalSpell(skill: KnownSkill, spell: string) {
  const normalizedSpell = normalizeCrystalToken(spell);
  return normalizeCrystalToken(skill.key) === normalizedSpell || normalizeCrystalToken(skill.name) === normalizedSpell;
}

function crystalBuffKey(objectId: string, buffType: number) {
  return `crystal-buff-${objectId}-${buffType}`;
}

function crystalSelfMovementTraits(
  currentWorld: WorldState,
  selfEntity?: WorldEntity | null,
) {
  const entity =
    selfEntity ??
    currentWorld.entities.find((candidate) => candidate.objectId === currentWorld.playerObjectId) ??
    null;
  const swiftFeet = currentWorld.activeBuffs.some((buff) => {
    const token = normalizeCrystalToken(`${buff.key} ${buff.name}`);
    const isSwiftFeet = buff.type === CRYSTAL_SWIFT_FEET_BUFF_TYPE || token.includes("swiftfeet");
    const active = buff.infinite === true || buff.remainingTicks > 0;
    return isSwiftFeet && buff.paused !== true && active;
  });
  return {
    mounted: Boolean(entity?.sprite?.mountLibrary),
    swiftFeet,
    sneaking: entity?.sneaking === true,
  };
}

function crystalSelfMovementProfile(
  currentWorld: WorldState,
  mode: "walk" | "run",
  selfEntity?: WorldEntity | null,
) {
  return crystalMovementProfile({
    mode,
    ...crystalSelfMovementTraits(currentWorld, selfEntity),
  });
}

function crystalEntityMovementFrameCount(
  entity: WorldEntity | null | undefined,
  mode: BevyMovementShadowMode,
) {
  return crystalEntityMovementAnimationProfile(entity, mode).frameCount;
}

function crystalEntityMovementAnimationProfile(
  entity: WorldEntity | null | undefined,
  mode: BevyMovementShadowMode,
) {
  const action = entity
    ? crystalFrameSetActionForState(
        crystalEntityFrameSet(entity),
        mode === "run" ? "running" : "walking",
      )
    : null;
  if (action) {
    return {
      frameCount: Math.max(action.count, 1),
      frameIntervalMs: Math.max(action.interval, 1),
    };
  }
  return {
    frameCount: entity?.sprite?.mountLibrary && mode === "walk" ? 8 : 6,
    frameIntervalMs: CRYSTAL_MOVE_FRAME_INTERVAL_MS,
  };
}

function crystalEntityFrameSet(entity: WorldEntity | null | undefined): OriginalSceneFrameSet | null {
  if (!entity || (entity.kind !== "monster" && entity.kind !== "npc")) return null;
  const libraryKey = entity.sprite?.bodyLibrary?.replaceAll("\\", "/");
  if (!libraryKey) return null;
  const entry = (crystalFrameSetCatalog.libraries as Record<
    string,
    { actionCount: number; actions: OriginalSceneFrameSet["actions"] }
  >)[libraryKey];
  return entry ? { count: entry.actionCount, actions: entry.actions } : null;
}

function crystalFrameSetActionDurationMs(action: OriginalSceneFrameSet["actions"][number]) {
  return Math.max(action.count, 1) * Math.max(action.interval, 1);
}

function crystalBuffRemainingTicks(expireTime: number | undefined) {
  if (typeof expireTime !== "number" || expireTime <= 0) {
    return 0;
  }

  const now = Date.now();
  return expireTime > now ? Math.max(0, Math.ceil((expireTime - now) / 1000)) : Math.max(0, Math.ceil(expireTime));
}

function normalizeCrystalToken(value: string) {
  return value.replace(/[^a-z0-9]/gi, "").toLowerCase();
}

function stringOrNull(value: unknown) {
  return typeof value === "string" ? value : null;
}

function stringOrFallback(value: unknown, fallback: string) {
  return typeof value === "string" ? value : fallback;
}

function tileDistance(source: WorldEntity | null, target: WorldEntity) {
  if (!source) return 0;
  return pointTileDistance(source, target);
}

function pointTileDistance(source: { x: number; y: number }, target: { x: number; y: number }) {
  return Math.max(Math.abs(source.x - target.x), Math.abs(source.y - target.y));
}

function entitySortRank(entity: WorldEntity, playerObjectId: string | null, selectedObjectId: string | null, self: WorldEntity | null) {
  if (entity.objectId === selectedObjectId) return 0;
  if (entity.objectId === playerObjectId) return 1;
  if (entity.dead) return 100 + tileDistance(self, entity);
  if (entity.kind === "monster") return 2 + tileDistance(self, entity);
  if (entity.kind === "player") return 20 + tileDistance(self, entity);
  return 40 + tileDistance(self, entity);
}

function directionToward(source: WorldEntity | null, target: WorldEntity) {
  if (!source) return target.direction ?? "Down";
  return directionFromPoint(source, target, target.direction ?? "Down");
}

function chooseCrystalSelfRenderPosition(
  serverSelf: { x: number; y: number } | null,
  ...candidates: Array<PredictedPlayerMotion | null>
) {
  if (!serverSelf) return candidates.find(Boolean) ?? null;
  return candidates
    .filter(
      (candidate): candidate is PredictedPlayerMotion =>
        candidate !== null &&
        crystalMovementCandidateNotBehindServer(serverSelf, candidate, candidate.direction),
    )
    // Clamp a candidate that has briefly outrun the server past the render lead cap
    // to the cap boundary (along its travel vector) instead of dropping it. Filtering
    // every over-cap candidate out makes this return null, and the renderer then falls
    // back to the authoritative server tile — the visible self-move "overshoot then
    // snap". Clamping keeps the sprite pinned at the cap so it eases forward as the
    // server catches up, with no backward jump. In-cap candidates pass through
    // untouched, so normal movement is unaffected.
    .map((candidate) =>
      Math.max(Math.abs(candidate.x - serverSelf.x), Math.abs(candidate.y - serverSelf.y)) <=
      MOVEMENT_LOCAL_RENDER_MAX_LEAD_TILES
        ? candidate
        : clampMovementLeadToCap(serverSelf, candidate, MOVEMENT_LOCAL_RENDER_MAX_LEAD_TILES),
    )
    .reduce<PredictedPlayerMotion | null>((best, candidate) => {
      if (!best) return candidate;
      const bestLead = Math.max(Math.abs(best.x - serverSelf.x), Math.abs(best.y - serverSelf.y));
      const candidateLead = Math.max(Math.abs(candidate.x - serverSelf.x), Math.abs(candidate.y - serverSelf.y));
      return candidateLead >= bestLead ? candidate : best;
    }, null);
}

function movementStepIntervalMs(mode: "walk" | "run") {
  return mode === "run" ? RUN_STEP_INTERVAL_MS : WALK_STEP_INTERVAL_MS;
}

function movementCommandDelayMs(mode: "walk" | "run") {
  return Math.max(100, movementStepIntervalMs(mode) - MOVEMENT_QUEUE_INPUT_LEAD_MS);
}

function crystalMovementActionToward(
  source: { x: number; y: number; direction?: string },
  target: { x: number; y: number },
  requestedMode: "walk" | "run",
  runDistance = 2,
): { point: { x: number; y: number }; direction: string; mode: "walk" | "run" } {
  if (source.x === target.x && source.y === target.y) {
    return {
      point: { x: source.x, y: source.y },
      direction: source.direction ?? "Down",
      mode: "walk",
    };
  }

  const remainingDistance = Math.max(Math.abs(target.x - source.x), Math.abs(target.y - source.y));
  const normalizedRunDistance = Math.max(2, Math.min(3, Math.trunc(runDistance)));
  const mode = requestedMode === "run" && remainingDistance >= normalizedRunDistance ? "run" : "walk";
  const direction = directionFromPoint(source, target, source.direction ?? "Down");
  return {
    point: pointMoveInDirection(source, direction, mode === "run" ? normalizedRunDistance : 1),
    direction,
    mode,
  };
}

function pointMoveInDirection(source: { x: number; y: number }, direction: string, distance: number) {
  switch (direction) {
    case "Up":
      return { x: source.x, y: source.y - distance };
    case "UpRight":
      return { x: source.x + distance, y: source.y - distance };
    case "Right":
      return { x: source.x + distance, y: source.y };
    case "DownRight":
      return { x: source.x + distance, y: source.y + distance };
    case "Down":
      return { x: source.x, y: source.y + distance };
    case "DownLeft":
      return { x: source.x - distance, y: source.y + distance };
    case "Left":
      return { x: source.x - distance, y: source.y };
    case "UpLeft":
      return { x: source.x - distance, y: source.y - distance };
    default:
      return { x: source.x, y: source.y };
  }
}

function directionVector(direction: string | undefined) {
  switch (direction) {
    case "Up":
      return { x: 0, y: -1 };
    case "UpRight":
      return { x: 1, y: -1 };
    case "Right":
      return { x: 1, y: 0 };
    case "DownRight":
      return { x: 1, y: 1 };
    case "Down":
      return { x: 0, y: 1 };
    case "DownLeft":
      return { x: -1, y: 1 };
    case "Left":
      return { x: -1, y: 0 };
    case "UpLeft":
      return { x: -1, y: -1 };
    default:
      return null;
  }
}

function movementDirectionsOppose(left: string | undefined, right: string | undefined) {
  const leftVector = directionVector(left);
  const rightVector = directionVector(right);
  if (!leftVector || !rightVector) {
    return false;
  }
  return leftVector.x * rightVector.x + leftVector.y * rightVector.y < 0;
}

function predictedPlayerAheadOfServer(
  server: { x: number; y: number },
  predicted: PredictedPlayerMotion,
  direction?: string,
) {
  const predictedDirection = predicted.direction ?? direction;
  if (!predictedDirection) return false;

  for (let distance = 1; distance <= MOVEMENT_LOCAL_ACTION_MAX_LEAD_TILES; distance += 1) {
    const point = pointMoveInDirection(server, predictedDirection, distance);
    if (point.x === predicted.x && point.y === predicted.y) {
      return true;
    }
  }

  return false;
}

function crystalMovementCandidateNotBehindServer(
  server: { x: number; y: number },
  candidate: PredictedPlayerMotion,
  direction?: string,
) {
  if (candidate.x === server.x && candidate.y === server.y) {
    return true;
  }
  return predictedPlayerAheadOfServer(server, candidate, direction);
}

function directionFromPoint(
  source: { x: number; y: number },
  target: { x: number; y: number },
  fallback = "Down",
) {
  const dx = Math.sign(target.x - source.x);
  const dy = Math.sign(target.y - source.y);
  if (dx === 0 && dy < 0) return "Up";
  if (dx > 0 && dy < 0) return "UpRight";
  if (dx > 0 && dy === 0) return "Right";
  if (dx > 0 && dy > 0) return "DownRight";
  if (dx === 0 && dy > 0) return "Down";
  if (dx < 0 && dy > 0) return "DownLeft";
  if (dx < 0 && dy === 0) return "Left";
  if (dx < 0 && dy < 0) return "UpLeft";
  return fallback;
}

function approachDestination(source: WorldEntity | null, target: { x: number; y: number }) {
  if (!source) return { x: target.x, y: target.y };
  if (pointTileDistance(source, target) <= 1) return { x: source.x, y: source.y };

  const dx = Math.sign(target.x - source.x);
  const dy = Math.sign(target.y - source.y);
  const absX = Math.abs(target.x - source.x);
  const absY = Math.abs(target.y - source.y);

  if (dx !== 0 && absX >= absY) {
    return { x: target.x - dx, y: target.y };
  }
  if (dy !== 0) {
    return { x: target.x, y: target.y - dy };
  }
  return { x: target.x - dx, y: target.y - dy };
}

function entityKindClassName(kind: EntityKind) {
  return kind === "selfPlayer" ? "self" : kind === "player" ? "player" : kind;
}

function parseCharacters(
  payload: Record<string, unknown>,
  fallbackName: string,
  language: Mir2Language,
): SelectCharacterEntry[] {
  const hasAuthoritativeCharacterList =
    Array.isArray(payload.characters) || Array.isArray(payload.Characters);
  const candidates = Array.isArray(payload.characters)
    ? payload.characters
    : Array.isArray(payload.Characters)
      ? payload.Characters
      : [];

  const parsed = candidates
    .map((entry, index) => toCharacterEntry(entry, index, language))
    .filter((entry): entry is SelectCharacterEntry => entry !== null);

  if (parsed.length > 0) {
    return parsed;
  }

  // An explicit empty list from LoginSuccess means this account genuinely has
  // no characters. Rendering a synthetic index-0 Warrior makes StartGame target
  // a save that does not exist and prevents first-character creation from being
  // a truthful product flow.
  if (hasAuthoritativeCharacterList) {
    return [];
  }

  return [fallbackCharacter(language, fallbackName)];
}

function toCharacterEntry(
  entry: unknown,
  fallbackIndex: number,
  language: Mir2Language,
): SelectCharacterEntry | null {
  if (!entry || typeof entry !== "object") {
    return null;
  }

  const value = entry as Record<string, unknown>;
  const translator = buildTranslator(language);
  const never = translator("client.Never", [], "Never");
  const binaryLastAccess = formatCrystalBinaryDateTime(
    value.lastAccessBinaryDatetime ?? value.last_access_binary_datetime,
    never,
  );
  return {
    index: typeof value.index === "number" ? value.index : typeof value.Index === "number" ? value.Index : fallbackIndex,
    name: stringOrFallback(value.name ?? value.Name, translator("ui.characterSlotFallback", [fallbackIndex + 1])),
    level: numberOrZero(value.level ?? value.Level) || 1,
    classKey: mapClassKey(value.class ?? value.Class),
    gender: mapGenderKey(value.gender ?? value.Gender),
    lastAccess:
      binaryLastAccess ?? stringOrFallback(value.lastAccess ?? value.LastAccess, never),
  };
}

function formatCrystalBinaryDateTime(value: unknown, never: string): string | null {
  if (typeof value !== "string" && typeof value !== "number" && typeof value !== "bigint") {
    return null;
  }

  let binary: bigint;
  try {
    binary = BigInt(value);
  } catch {
    return null;
  }
  if (binary === 0n) return never;

  const bits = BigInt.asUintN(64, binary);
  const ticks = bits & 0x3fff_ffff_ffff_ffffn;
  const kind = bits & 0xc000_0000_0000_0000n;
  const unixMilliseconds = Number((ticks - 621_355_968_000_000_000n) / 10_000n);
  const date = new Date(unixMilliseconds);
  if (!Number.isFinite(unixMilliseconds) || Number.isNaN(date.getTime())) return never;

  const local = kind === 0x8000_0000_0000_0000n || kind === 0xc000_0000_0000_0000n;
  const year = local ? date.getFullYear() : date.getUTCFullYear();
  const month = (local ? date.getMonth() : date.getUTCMonth()) + 1;
  const day = local ? date.getDate() : date.getUTCDate();
  const hour = local ? date.getHours() : date.getUTCHours();
  const minute = local ? date.getMinutes() : date.getUTCMinutes();
  const second = local ? date.getSeconds() : date.getUTCSeconds();
  const pad = (part: number) => String(part).padStart(2, "0");
  return `${String(year).padStart(4, "0")}/${pad(month)}/${pad(day)} ${pad(hour)}:${pad(minute)}:${pad(second)}`;
}

function fallbackCharacter(language: Mir2Language, fallbackName = ""): SelectCharacterEntry {
  const translator = buildTranslator(language);
  return {
    index: 0,
    name: fallbackName || translator("ui.characterFallbackName"),
    level: 1,
    classKey: "warrior",
    gender: "male",
    lastAccess: translator("client.Never", [], "Never"),
    synthetic: true,
  };
}

function isFallbackCharacter(entry: SelectCharacterEntry) {
  return entry.index === 0 && entry.level === 1 && entry.classKey === "warrior";
}

function mapClassKey(value: unknown): SelectCharacterEntry["classKey"] {
  if (typeof value === "string") {
    const normalized = value.toLowerCase();
    if (normalized.includes("wizard")) return "wizard";
    if (normalized.includes("tao")) return "taoist";
    if (normalized.includes("assassin")) return "assassin";
    if (normalized.includes("archer")) return "archer";
    return "warrior";
  }

  if (typeof value === "number") {
    return value === 1 ? "wizard" : value === 2 ? "taoist" : value === 3 ? "assassin" : value === 4 ? "archer" : "warrior";
  }

  return "warrior";
}

function rankingPageKey(rankType: number, onlineOnly: boolean) {
  return `${rankType}:${onlineOnly ? "online" : "all"}`;
}

function mapGenderKey(value: unknown): SelectCharacterEntry["gender"] {
  if (typeof value === "string") {
    return value.toLowerCase().includes("female") ? "female" : "male";
  }

  if (typeof value === "number") {
    return value === 1 ? "female" : "male";
  }

  return "male";
}
